class Server(BaseModelWithConfig):
    url: AnyUrl | str
    description: str | None = None
    variables: dict[str, ServerVariable] | None = None

    @field_validator('url', mode='before')
    @classmethod
    def clean_url(cls, v: Any) -> Any:
        if isinstance(v, str):
            return v.replace("root_path", "").replace("/root_path", "")
        return v

    @field_validator('description')
    @classmethod
    def escape_description(cls, v: str | None) -> str | None:
        if v is None:
            return None
        return v.replace('\\', '\\\\').replace('"', '\\"')
